  Future<void> _onMsg(Map<String, dynamic> frame) async {
    final id = frame['id'] as String? ?? '';
    if (id.isEmpty || _identity == null) return;
    if (_seenFrameIds.contains(id)) return; // dedup by id (at-least-once)
    _seenFrameIds.add(id);
    if (_seenFrameIds.length > _seenFrameIdsCap) _seenFrameIds.removeAt(0);
    final from = frame['from'] as String? ?? '';
    final channel = frame['channel'] as String?;
    if (channel != null) {
      await _onChannelMsg(frame, id, channel, from);
      return;
    }
    String text;
    try {
      var dhB64 = _dhKeys[from];
      if (dhB64 == null) {
        // The sender's DH key arrives with whois; resolve, then decrypt.
        await _whois(from);
        dhB64 = _dhKeys[from];
      }
      if (dhB64 == null) throw StateError('no DH key for $from');
      text = await hubDecryptPayload(
        ourIdentity: _identity!,
        senderDhPubkey: SimplePublicKey(
          base64Decode(dhB64),
          type: KeyPairType.x25519,
        ),
        frameId: id,
        ciphertextB64: frame['ciphertext'] as String? ?? '',
      );
    } on Object catch (error) {
      // Undecryptable (unknown sender key, tampered payload): never deliver
      // opaque ciphertext into the chat — drop with a diagnostic.
      _log('dropped undecryptable DM from $from: $error');
      return;
    }
    _inbox.add(
      AgentMessage(
        id: id,
        fromId: from,
        toId: agentId ?? '',
        text: text,
        sentAt: DateTime.fromMillisecondsSinceEpoch(
          frame['ts'] as int? ?? 0,
        ).toUtc().toIso8601String(),
      ),
    );
  }

  Future<void> _onChannelMsg(
    Map<String, dynamic> frame,
    String id,
    String channel,
    String from,
  ) async {
    // Some hubs fan out to the sender too; own channel echo is not new
    // steering (the local transcript already has the tool result).
    if (from == agentId || !_channels.containsKey(channel)) return;
    final keys = _channels[channel];
    String text;
    try {
      if (keys == null) {
        text = _decodePublicChannelPayload(
          frame['ciphertext'] as String? ?? '',
        );
      } else {
        text = await _decryptKeyedChannelMail(
          keys,
          channel,
          from,
          id,
          frame['ciphertext'] as String? ?? '',
        );
      }
    } on Object {
      // Never print the error here: base64 parsers can echo their input,
      // which is invite key material on this path.
      _log('dropped undecryptable channel mail from $from');
      return;
    }
    _inbox.add(
      AgentMessage(
        id: id,
        fromId: from,
        toId: '#$channel',
        text: text,
        sentAt: DateTime.fromMillisecondsSinceEpoch(
          frame['ts'] as int? ?? 0,
        ).toUtc().toIso8601String(),
      ),
    );
  }

  /// Decrypts key-holding channel mail: `fanet1` self-describing frames
  /// FIRST (the sender X25519 pubkey rides in the frame — the fa_network /
  /// app envelope contract, and what the CLI fabric now sends), falling
  /// back to the legacy raw `dap/1` layout (sender key via whois).
  Future<String> _decryptKeyedChannelMail(
    HubChannelKeys keys,
    String channel,
    String from,
    String id,
    String payloadB64,
  ) async {
    final channelPub = SimplePublicKey(
      base64Decode(keys.pub),
      type: KeyPairType.x25519,
    );
    final keyPair = SimpleKeyPairData(
      base64Decode(keys.priv),
      publicKey: channelPub,
      type: KeyPairType.x25519,
    );
    final fanet1 = hubTryOpenFanet1(payloadB64);
    if (fanet1 != null) {
      try {
        return await hubDecryptPayloadWithKeyPair(
          recipientDhKeyPair: keyPair,
          senderDhPubkey: fanet1.senderPubkey,
          frameId: id,
          aadTarget: channel,
          ciphertextB64: fanet1.ciphertextB64,
        );
      } on Object {
        // Shape detection is not proof: a legacy nonce can start with
        // 0x01 by chance. A failed fanet1 open falls back to the legacy
        // layout — the frame is dropped only when BOTH paths fail.
      }
    }
    var dhB64 = _dhKeys[from];
    if (dhB64 == null) {
      await _whois(from);
      dhB64 = _dhKeys[from];
    }
    if (dhB64 == null) throw StateError('no sender DH key');
    return hubDecryptPayloadWithKeyPair(
      recipientDhKeyPair: keyPair,
      senderDhPubkey: SimplePublicKey(
        base64Decode(dhB64),
        type: KeyPairType.x25519,
      ),
      frameId: id,
      aadTarget: channel,
      ciphertextB64: payloadB64,
    );
  }

  void _onAgentInfo(Map<String, dynamic> frame) {
    final agentId = frame['agentId'] as String? ?? '';
    final peer = HubPeer(
      agentId: agentId,
      name: frame['name'] as String?,
      online: frame['online'] as bool? ?? false,
    );
    _whoisCache[agentId] = peer;
    final dh = frame['x25519'] as String?;
    if (dh != null && dh.isNotEmpty) _dhKeys[agentId] = dh;
    final waiters = _pendingWhois.remove(agentId);
    if (waiters == null) return;
    for (final waiter in waiters) {
      if (!waiter.isCompleted) waiter.complete(peer);
    }
  }

  void _onPresence(Map<String, dynamic> frame) {
    final replyTo = frame['replyTo'] as String?;
    final agents = [
      for (final entry in (frame['agents'] as List? ?? const []))
        if (entry is Map)
          HubPeer(
            agentId: entry['agentId'] as String? ?? '',
            name: entry['name'] as String?,
            online: entry['online'] as bool? ?? false,
          ),
    ];
    if (replyTo != null) {
      final waiter = _pendingPresence.remove(replyTo);
      if (waiter != null && !waiter.isCompleted) {
        waiter.complete(agents);
        return;
      }
    }
    // Legacy hub (no replyTo echo): complete the oldest waiter.
    if (_pendingPresence.isNotEmpty) {
      final waiter = _pendingPresence.remove(_pendingPresence.keys.first)!;
      if (!waiter.isCompleted) waiter.complete(agents);
    }
  }

  /// Whois with caching — the spec-required lookup before a DM.
  Future<HubPeer> _whois(String agentId) async {
    if (agentId.isEmpty) throw ArgumentError('whois needs an agent id');
    final cached = _whoisCache[agentId];
    if (cached != null) return cached;
    final waiter = Completer<HubPeer>();
    _pendingWhois.putIfAbsent(agentId, () => []).add(waiter);
    await _sendNow({'op': 'whois', 'agentId': agentId});
    final peer = await waiter.future.timeout(_replyTimeout);
    _whoisCache[agentId] = peer;
    return peer;
  }

  Future<List<HubPeer>> _presenceQuery() async {
    if (!isConnected) throw StateError('hub link is not connected');
    final id = newHubFrameId();
    final waiter = Completer<List<HubPeer>>();
    _pendingPresence[id] = waiter;
    await _sendNow({'op': 'presence_query', 'id': id});
    try {
      return await waiter.future.timeout(_replyTimeout);
    } on Object {
      _pendingPresence.remove(id);
      rethrow;
    }
  }

