/// The hub as the messaging fabric's primary transport (issue #27 phase 1):
/// a [MessagingRepository] over the DAP hub client, composed with the file
/// fabric through `FallbackMessagingRepository`.
///
/// Lives in `bin/` on purpose — `package:fa_hub_client` pulls `dart:io`
/// (WebSocket, key files) and `lib/src/**` stays web-pure, exactly like the
/// `hub` plugin host in `fah_hub_plugin.dart`. The harness's pure
/// `RoutingMessagingRepository` capability is what lets the composition
/// route without knowing anything about DAP.
///
/// Mapping to the hub model:
/// * presence/registration ride the signed hello (`register`/`touch` are
///   deliberate no-ops — the display name is the DAP identity, stable
///   across restarts);
/// * `send` targets are resolved against the hub roster BEFORE the call
///   ([resolveTarget] — exact 16-hex id, unique display name, or `#channel`);
/// * inbound frames land in the package repository's in-memory inbox keyed
///   by OUR hub agent id, so `peek`/`drain` ignore the fabric agentId (the
///   composition guards that only the wired `primaryMailbox` reaches here);
/// * `directory` maps the hub roster (online AND offline — the hub keeps
///   offline mailboxes and flushes them on the peer's next connect) onto
///   mailbox entries.
library;

import 'dart:convert';

import 'package:fa_hub_client/fa_hub_client.dart' as hub;
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// The hub-fabric gate (issue #304 E6, mirrors `images.registry: false`):
/// the CLI wires the hub as the fabric's primary transport only when the
/// `hub` plugin is enabled, DAP is unlocked (`DAP_MASTER_SECRET`) and the
/// `fabric.hub` kill switch is not off. With the switch off the fabric is
/// the bare file layer and `agent_directory` reproduces the legacy
/// listing byte-for-byte (REG).
bool hubFabricWired({
  required bool hubPluginEnabled,
  required bool fabricHubAllowed,
}) => hubPluginEnabled && fabricHubAllowed;

/// Hub-backed [MessagingRepository] over a [hub.HubPlugin].
final class HubFabricRepository
    implements MessagingRepository, RoutingMessagingRepository {
  HubFabricRepository(
    this._plugin, {
    this.repositoryResolver,
    this.publicChannelChecker,
    this.privateKeyMissingChecker,
    this.channelLister,
  });

  final hub.HubPlugin _plugin;

  /// Resolves the host's ACTIVE repository (a scoped, host-owned client
  /// when a join enrolled a name-bound credential) — falls back to the
  /// vendored plugin's repository when absent.
  final hub.HubMessagingRepository? Function(hub.HubPlugin plugin)?
  repositoryResolver;

  /// Whether [channel] is a PUBLIC showcase channel (keyless membership):
  /// those carry `base64({"text": …})` payloads, not DAP/1 chankey E2E —
  /// sending encrypted frames there renders "(unable to decrypt)" in
  /// the app (fa_network showcase contract).
  final Future<bool> Function(hub.HubPlugin plugin, String channel)?
  publicChannelChecker;

  /// True when [channel] is a STORED-private membership whose key could
  /// not be resolved at runtime (missing passphrase). Sending must then
  /// REFUSE loudly — never downgrade to a hub-readable payload and never
  /// auto-keygen a key no other member has (gh-1888 review).
  final Future<bool> Function(hub.HubPlugin plugin, String channel)?
  privateKeyMissingChecker;

  /// Lists the joined channel ids: their `#channel` inboxes are drained
  /// alongside the agent's own inbox (DM-only draining drops channel
  /// traffic entirely).
  final Future<List<String>> Function(hub.HubPlugin plugin)? channelLister;

  hub.HubMessagingRepository? get _repo =>
      repositoryResolver?.call(_plugin) ?? _plugin.repository;

  String? get _agentId => _repo?.client.agentId ?? _plugin.agentId;

  @override
  bool get isConnected => _repo?.client.connected ?? false;

  @override
  Future<String?> resolveTarget(String toId) async {
    if (!isConnected) return null;
    // Channels are always hub-shaped (the package client routes the send
    // and auto-creates unknown channels on first use — except on
    // master-gated hubs (hub.fa1.dev), where joining an unknown channel
    // is access_denied and only a master connection creates channels).
    if (toId.startsWith('#')) return toId;
    final me = _agentId;
    if (me != null && toId == me) return null; // our own fabric mailbox
    // A FAILED roster query (drop/timeout mid-query) RETHROWS — the
    // composition's flush distinguishes "query failed, retry later" from
    // a confirmed roster miss (a null answer here), and its send-routing
    // `_safeResolve` still collapses the throw to the file fallback
    // (issue #988's never-escape guarantee lives at that boundary). The
    // bin adapter used to collapse the failure to null itself, which
    // read as a confirmed miss and untracked queued hub mail forever
    // (gh-1838 hostile-env strand).
    final roster = await _repo!.client.presenceQuery();
    for (final agent in roster) {
      if (agent.agentId == toId) return toId; // exact id wins
    }
    final byName = roster.where((agent) => agent.name == toId).toList();
    // A display name resolves only when it is unambiguous — matches the
    // dap_dm resolver; an ambiguous name falls through to the file fabric
    // where the session-name resolution owns it.
    return byName.length == 1 ? byName.single.agentId : null;
  }

  /// The hub roster, or null when the query fails (drop mid-query,
  /// reconnect in flight) — callers fall back to the file fabric.
  Future<List<hub.AgentInfo>?> _presenceRoster() async {
    try {
      return await _repo!.client.presenceQuery();
    } on Object {
      return null;
    }
  }

  @override
  Future<void> send(AgentMessage message) async {
    final repo = _repo;
    final agentId = _agentId;
    if (repo == null || agentId == null) {
      throw StateError('hub fabric not connected — no hub client');
    }
    final toId = message.toId;
    if (toId.startsWith('#') &&
        await (publicChannelChecker?.call(_plugin, toId.substring(1)) ??
            false)) {
      // Public showcase channel: raw base64({"text": …}) payload — the
      // app's contract, readable by every member with the link.
      await repo.client.sendChannelEnvelope(toId.substring(1), (frameId) async {
        return base64Encode(utf8.encode(jsonEncode({'text': message.text})));
      });
      return;
    }
    if (toId.startsWith('#')) {
      final channel = toId.substring(1);
      // A stored-private membership whose key failed to resolve must
      // never downgrade: refuse loudly so the composition queues/retries
      // instead of emitting a hub-readable (or wrong-key) frame.
      if (await (privateKeyMissingChecker?.call(_plugin, channel) ?? false)) {
        throw StateError(
          'refusing to send to #$channel: the private channel key is '
          'unavailable (set DAP_KEY_PASSPHRASE or rejoin with the '
          'invite)',
        );
      }
      // Private fa_network channel: carry senderX in the frame so the app
      // can open it with the channel key alone (no whois/senderKey lookup).
      await repo.client.sendChannelFanet1(channel, message.text);
      return;
    }
    await repo.send(
      hub.AgentMessage(
        id: message.id,
        fromId: agentId,
        toId: toId,
        text: message.text,
        sentAt: message.sentAt,
      ),
    );
  }

  @override
  Future<List<AgentMessage>> peek(String agentId) async {
    final repo = _repo;
    final inbox = _agentId;
    if (repo == null || inbox == null) return const [];
    try {
      final channels = channelLister == null
          ? const <String>[]
          : await channelLister!.call(_plugin);
      return _fromHub([
        ...await repo.peek(inbox),
        for (final channel in channels) ...await repo.peek('#$channel'),
      ]);
    } on Object {
      return const [];
    }
  }

  @override
  Future<List<AgentMessage>> drain(String agentId) async {
    final repo = _repo;
    final inbox = _agentId;
    if (repo == null || inbox == null) return const [];
    try {
      final channels = channelLister == null
          ? const <String>[]
          : await channelLister!.call(_plugin);
      final me = _agentId;
      return _fromHub([
        ...await repo.drain(inbox),
        for (final channel in channels) ...await repo.drain('#$channel'),
        // Channel sends echo back to the sender: my own posts are not
        // new mail (and must never trigger a self-reply loop).
      ]).where((m) => m.fromId != me || !m.toId.startsWith('#')).toList();
    } on Object {
      return const [];
    }
  }

  /// Maps the package's mirrored AgentMessage onto the harness type. The
  /// package already reports the true recipient: OUR hub agent id for
  /// DMs, `#channel` for channel traffic — preserving it keeps channel
  /// attribution (and the leave filter) intact.
  List<AgentMessage> _fromHub(List<hub.AgentMessage> messages) => [
    for (final message in messages)
      AgentMessage(
        id: message.id,
        fromId: message.fromId,
        toId: message.toId,
        text: message.text,
        sentAt: message.sentAt,
        hops: message.hops,
      ),
  ];

  @override
  Future<void> register(
    String agentId, {
    String? sessionName,
    List<AgentCapability> capabilities = const [],
  }) async {
    // Presence rides the signed hello; the hub display name is the DAP
    // identity (stable across restarts), not the per-session fabric name.
    // Capabilities are not carried by the hub wire yet — the file fabric's
    // `.capabilities` marker is the discovery source (issue #27 phase 2).
  }

  @override
  Future<void> touch(String agentId, {bool busy = false}) async {
    // Hub liveness is the connection itself; the hub dates peers by their
    // last authenticated frame (lastSeen), not by client heartbeats. The
    // busy run-state is local knowledge (file marker) until the hub wire
    // carries presence states.
  }

  @override
  Future<List<MailboxEntry>> directory() async {
    final repo = _repo;
    if (repo == null) return const [];
    // Same guard as resolveTarget: a hub drop mid-query (the client fails
    // the waiter with StateError('connection closed')) must fall back to
    // the file fabric, never crash the caller (ffb6aa67b pattern).
    final roster = await _presenceRoster();
    if (roster == null) return const [];
    return [
      for (final agent in roster)
        MailboxEntry(
          id: agent.agentId,
          name: agent.name,
          lastActivity: agent.lastSeen,
          // Registration-backed presence: the hub knows who is connected —
          // no mtime heuristic.
          presence: agent.online ? AgentPresence.live : AgentPresence.offline,
          // Hub-sourced marker (issue #304 AC3): the directory renders the
          // `[hub]` tag so DAP peers read apart from file mailboxes.
          source: mailboxSourceHub,
        ),
    ];
  }
}

